    "Unlisted" : "Sin listar",
    "Direct" : "Directa",
    "Your posts do best around {hour}:00 UTC — {n} engagement each, over {posts} posts." : "As tuyas publicacions funcionan millor arredol d'as {hour}:00 UTC: {n} d'interacción cadaguna, en {posts} publicacions.",
    "Boosts of other people" : "Impulsos d'atras personas",
    "Counted over your {count} most recent posts, which is as far back as this page goes." : "Contau sobre as tuyas {count} publicacions mas recients, que ye dica an plega ista pachina.",
    "_Counted over your one post._::_Counted over all {count} of your posts._" : ["Contau sobre a tuya unica publicación ({count}).","Contau sobre totas as tuyas {count} publicacions."],
    "Could not work out your statistics." : "No s'han puesto calcular as tuyas estatisticas.",
    "Could not download your statistics" : "No s'han puesto descargar as tuyas estatisticas",
    "new" : "nuevo",
    "_%n engagement in {month}_::_%n engagement in {month}_" : ["%n interacción en {month}","%n interaccions en {month}"],
    "_%n follower in {month}_::_%n followers in {month}_" : ["%n seguidor en {month}","%n seguidors en {month}"],
